package studio.adnes;
import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;
public class AdnesStudio extends JavaPlugin {
 private BossManager bossManager;
 public void onEnable(){saveDefaultConfig();bossManager=new BossManager(this);new AbilityManager(this);getLogger().info("ADNes Studio listo para Paper 1.12.2 / Java 8");}
 public void onDisable(){if(bossManager!=null)bossManager.cleanup();}
 public boolean onCommand(CommandSender s,Command c,String label,String[] a){if(!c.getName().equalsIgnoreCase("adnes"))return false;if(a.length==0){s.sendMessage(ChatColor.AQUA+"/adnes <items|give|boss|spawn|removeboss|reload>");return true;}if(a[0].equalsIgnoreCase("reload")){if(!s.hasPermission("adnes.admin"))return no(s);reloadConfig();s.sendMessage(ChatColor.GREEN+"Configuracion recargada.");return true;}if(a[0].equalsIgnoreCase("items")){s.sendMessage(ChatColor.GOLD+"Catalogo Nexus/Lunar:");s.sendMessage(ChatColor.YELLOW+CustomItems.listIds());s.sendMessage(ChatColor.GRAY+"/adnes give <jugador> <id>");return true;}if(a[0].equalsIgnoreCase("give")&&a.length>=3){if(!s.hasPermission("adnes.admin"))return no(s);Player p=Bukkit.getPlayer(a[1]);if(p==null){s.sendMessage(ChatColor.RED+"Jugador no encontrado.");return true;}org.bukkit.inventory.ItemStack it=CustomItems.create(this,a[2]);if(it==null){s.sendMessage(ChatColor.RED+"ID desconocido: "+a[2]+". Usa /adnes items.");return true;}for(org.bukkit.inventory.ItemStack extra:p.getInventory().addItem(it).values())p.getWorld().dropItemNaturally(p.getLocation(),extra);s.sendMessage(ChatColor.GREEN+"Entregado "+a[2]+" a "+p.getName());return true;}if(a[0].equalsIgnoreCase("boss")||a[0].equalsIgnoreCase("spawn")){if(!(s instanceof Player)){s.sendMessage("Solo jugadores.");return true;}if(!s.hasPermission("adnes.admin"))return no(s);bossManager.spawn((Player)s);s.sendMessage(ChatColor.DARK_PURPLE+"Shadow Sorcerer invocado.");return true;}if(a[0].equalsIgnoreCase("removeboss")){if(!s.hasPermission("adnes.admin"))return no(s);int n=bossManager.removeNearby(s instanceof Player?((Player)s).getLocation():null);s.sendMessage(ChatColor.GREEN+"Jefes eliminados: "+n);return true;}s.sendMessage(ChatColor.RED+"Subcomando no valido.");return true;}
 private boolean no(CommandSender s){s.sendMessage(ChatColor.RED+"No tienes permiso.");return true;}
}